sha=lambda s:hashlib.sha256(s.encode()).hexdigest()
prepared=[]
for name,before,after,edits in data:
    p=Path(name);s=p.read_text()
    if sha(s)!=before:raise RuntimeError('Base changed: '+name)
    for start,n,value in reversed(edits):s=s[:start]+value+s[start+n:]
    if sha(s)!=after:raise RuntimeError('Output mismatch: '+name)
    prepared.append((p,s))
for p,s in prepared:p.write_text(s)
